<student_code untrusted="true">
=== correct_alt_style.ino ===
   1| /*
   2|  * Button toggles the LED, with software debounce.
   3|  * D2 = button (active low), LED_BUILTIN = LED, Serial1 = status output.
   4|  */
   5| 
   6| #define BTN 2
   7| 
   8| enum State { RELEASED, MAYBE_PRESSED, PRESSED, MAYBE_RELEASED };
   9| 
  10| State state = RELEASED;
  11| unsigned long timerStart;
  12| bool led = false;
  13| 
  14| void report() {
  15|   if (led) {
  16|     Serial1.print("ON\n");
  17|   } else {
  18|     Serial1.print("OFF\n");
  19|   }
  20| }
  21| 
  22| void setup() {
  23|   pinMode(BTN, INPUT_PULLUP);
  24|   pinMode(LED_BUILTIN, OUTPUT);
  25|   digitalWrite(LED_BUILTIN, LOW);
  26|   Serial1.begin(9600);
  27| }
  28| 
  29| void loop() {
  30|   bool down = (digitalRead(BTN) == LOW);
  31|   unsigned long now = millis();
  32| 
  33|   switch (state) {
  34|     case RELEASED:
  35|       if (down) { state = MAYBE_PRESSED; timerStart = now; }
  36|       break;
  37|     case MAYBE_PRESSED:
  38|       if (!down) {
  39|         state = RELEASED;
  40|       } else if (now - timerStart >= 10) {
  41|         state = PRESSED;
  42|         led = !led;
  43|         digitalWrite(LED_BUILTIN, led);
  44|         report();
  45|       }
  46|       break;
  47|     case PRESSED:
  48|       if (!down) { state = MAYBE_RELEASED; timerStart = now; }
  49|       break;
  50|     case MAYBE_RELEASED:
  51|       if (down) {
  52|         state = PRESSED;
  53|       } else if (now - timerStart >= 10) {
  54|         state = RELEASED;
  55|       }
  56|       break;
  57|   }
  58| }
</student_code>
